from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
css='''<style id="blaskos-allergen-v12">\n/* V12: force a genuinely narrow menu column; this style is deliberately appended last so older V6/V8 rules cannot override it. */\n#docsAllergens .allergen-table{table-layout:fixed!important;min-width:706px!important;width:706px!important}\n#docsAllergens .allergen-table thead tr th:first-child,#docsAllergens .allergen-table tbody tr td:first-child{width:90px!important;min-width:90px!important;max-width:90px!important;box-sizing:border-box!important}\n#docsAllergens .allergen-table thead tr th:nth-child(n+2):nth-child(-n+15),#docsAllergens .allergen-table tbody tr td:nth-child(n+2):nth-child(-n+15){width:44px!important;min-width:44px!important;max-width:44px!important}\n#docsAllergens .allergen-table thead tr th:last-child,#docsAllergens .allergen-table tbody tr td:last-child{width:1px!important;min-width:1px!important}\n#docsAllergens .allergen-table th:first-child{padding:7px 6px!important}\n#docsAllergens .allergen-table td:first-child{padding:7px 22px 7px 7px!important}\n#docsAllergens .allergen-table td:first-child b{font-size:10px!important;line-height:1.15!important;max-width:78px!important}\n#docsAllergens .allergen-table td:first-child .allergen-status{font-size:7px!important;margin-top:4px!important}\n#docsAllergens .allergen-table .allergen-actions{right:2px!important;top:16px!important;gap:2px!important}\n#docsAllergens .allergen-table .allergen-actions button{width:17px!important;height:17px!important}\n@media(max-width:620px){#docsAllergens .allergen-table{width:706px!important;min-width:706px!important}#docsAllergens .allergen-table thead tr th:first-child,#docsAllergens .allergen-table tbody tr td:first-child{width:90px!important;min-width:90px!important;max-width:90px!important}}\n</style>'''
pos=s.rfind('</head>')
if pos<0: raise SystemExit('No closing head found')
s=s[:pos]+css+'\n'+s[pos:]
p.write_text(s,encoding='utf-8')
